import { expect, test } from '../fixtures';

/** A value that is new on every run (an email, a name), so a second run does not collide with the first. */
function makeUnique(): (base: string) => string {
  const seen = new Map<string, string>();
  return (base) => {
    const known = seen.get(base);
    if (known) return known;
    const tag = Math.random().toString(36).slice(2, 8);
    const at = base.indexOf('@');
    const value = at === -1 ? `${base}-${tag}` : `${base.slice(0, at)}+${tag}${base.slice(at)}`;
    seen.set(base, value);
    return value;
  };
}

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Register valid', async ({ page }) => {
  const unique = makeUnique();

  await test.step('Open the registration page', async () => {
    await page.goto('/auth/register');
  });

  await test.step('Type a new username', async () => {
    await page.getByRole('textbox', { name: 'Username', exact: true }).fill(unique('newuser'));
  });

  await test.step('Type a new email', async () => {
    await page.getByRole('textbox', { name: 'Email address', exact: true }).fill(unique('newuser@example.com'));
  });

  await test.step('Type a password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('Newuser-Pass-1');
  });

  await test.step('Repeat the password', async () => {
    await page.getByRole('textbox', { name: 'Confirm password', exact: true }).fill('Newuser-Pass-1');
  });

  await test.step('Accept the terms', async () => {
    await page.getByRole('checkbox', { name: 'I accept the Terms of Service', exact: true }).click();
  });

  await test.step('Press Register', async () => {
    await page.getByRole('button', { name: 'Register', exact: true }).click();
  });

  await test.step('The new username is shown in the navbar, signed in [code]', async () => {
    await expect(page.locator('.navbar a[href*="/user/newuser-"]')).toBeVisible();
  });

  await test.step('The new member lands on the forum index [code]', async () => {
    await expect(page).toHaveURL(/localhost:5000\/$/);
  });
});
